#!/usr/bin/env node
// Differential harness: runs the Python executable and the Node port with the
// same argv and reports any divergence in stdout, stderr or exit status.
// The program name legitimately differs, so it is normalised before comparing.
import { spawnSync } from 'node:child_process';

const PY = '/workspace/dataset/test5_executable';
const JS = ['/output/test5.mjs'];

function normalise(text) {
  return text.split('test5_executable').join('«PROG»').split('test5.mjs').join('«PROG»');
}

export function compare(argv, env = {}) {
  const options = { encoding: 'buffer', env: { ...process.env, ...env } };
  const py = spawnSync(PY, argv, options);
  const js = spawnSync(process.execPath, [...JS, ...argv], options);
  const result = {
    argv,
    env,
    ok: true,
    py: {
      stdout: py.stdout.toString('utf8'),
      stderr: py.stderr.toString('utf8'),
      status: py.status,
    },
    js: {
      stdout: js.stdout.toString('utf8'),
      stderr: js.stderr.toString('utf8'),
      status: js.status,
    },
  };
  result.ok =
    normalise(result.py.stdout) === normalise(result.js.stdout) &&
    normalise(result.py.stderr) === normalise(result.js.stderr) &&
    result.py.status === result.js.status;
  return result;
}

export function report(cases) {
  let failures = 0;
  for (const testCase of cases) {
    const argv = Array.isArray(testCase) ? testCase : testCase.argv;
    const env = Array.isArray(testCase) ? {} : (testCase.env ?? {});
    const result = compare(argv, env);
    if (!result.ok) {
      failures += 1;
      console.log('MISMATCH', JSON.stringify({ argv, env }));
      console.log('  py:', JSON.stringify(result.py));
      console.log('  js:', JSON.stringify(result.js));
    }
  }
  console.log(`${cases.length - failures}/${cases.length} matched`);
  return failures;
}

if (process.argv[1] && process.argv[1].endsWith('difftest.mjs') && process.argv.length > 2) {
  const result = compare(process.argv.slice(2));
  console.log(JSON.stringify(result, null, 2));
  process.exit(result.ok ? 0 : 1);
}

/**
 * `int(str)` with base 10, following CPython's two-step conversion.
 *
 * Results are returned as BigInt because Python integers are unbounded: the
 * graph in this port uses the parsed values as node identities, so collapsing
 * them onto IEEE-754 doubles would merge distinct nodes such as
 * 99999999999999999999998 and 99999999999999999999999.
 */

import { decimalValue, isAsciiSpace, isNonAsciiSpace } from './unicode.mjs';
import { PyValueError } from './errors.mjs';

/**
 * `_PyUnicode_TransformDecimalAndSpaceToASCII`.
 *
 * ASCII code points are passed through untouched, other whitespace collapses to
 * a plain space, other decimal digits become their ASCII counterpart, and
 * anything else becomes '?' so the scanner below rejects it.
 */
function transformDecimalAndSpaceToAscii(text) {
  let out = '';
  for (const character of text) {
    const codePoint = character.codePointAt(0);
    if (codePoint < 127) {
      out += character;
    } else if (isNonAsciiSpace(codePoint)) {
      out += ' ';
    } else {
      const digit = decimalValue(codePoint);
      out += digit < 0 ? '?' : String(digit);
    }
  }
  return out;
}

function invalidLiteral(text) {
  return new PyValueError(
    `invalid literal for int() with base 10: ${JSON.stringify(text)}`,
  );
}

/**
 * `PyLong_FromString` for base 10: optional surrounding whitespace, an optional
 * sign that must be followed immediately by a digit, and digit groups that may
 * be separated by single underscores.
 *
 * @param {string} text
 * @returns {bigint}
 */
export function pyInt(text) {
  if (typeof text !== 'string') {
    throw new PyValueError('pyInt() expects a string');
  }

  const scanned = transformDecimalAndSpaceToAscii(text);
  const length = scanned.length;
  let index = 0;

  while (index < length && isAsciiSpace(scanned.charCodeAt(index))) index += 1;

  let negative = false;
  if (index < length && (scanned[index] === '+' || scanned[index] === '-')) {
    negative = scanned[index] === '-';
    index += 1;
  }

  let digits = '';
  let previousWasDigit = false;
  while (index < length) {
    const character = scanned[index];
    if (character >= '0' && character <= '9') {
      digits += character;
      previousWasDigit = true;
      index += 1;
    } else if (character === '_' && previousWasDigit) {
      // A single underscore is allowed, but only wedged between two digits;
      // `previousWasDigit` going false here rejects '1__0' and '5_'.
      previousWasDigit = false;
      index += 1;
    } else {
      break;
    }
  }

  if (digits === '' || !previousWasDigit) throw invalidLiteral(text);

  while (index < length && isAsciiSpace(scanned.charCodeAt(index))) index += 1;
  if (index !== length) throw invalidLiteral(text);

  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}

/**
 * The callable handed to `parser.add_argument(..., type=int)`. `typeName` stands
 * in for Python's `int.__name__`, which argparse interpolates into its
 * "invalid int value" diagnostic.
 */
export const int = (text) => pyInt(text);
int.typeName = 'int';

/**
 * Unicode character classification mirroring the CPython predicates that the
 * ported code depends on.
 *
 * Everything here is derived from the runtime's own Unicode tables via regular
 * expression property escapes, so no character data is bundled or vendored.
 */

const RE_DECIMAL_DIGIT = /^\p{Nd}$/u;

/**
 * `str.isprintable()` treats a character as non-printable when its general
 * category is one of Cc, Cf, Cs, Co, Cn, Zl, Zp or Zs -- with the single space
 * U+0020 carved out as printable.
 */
const RE_NONPRINTABLE = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;

/**
 * The ASCII characters `Py_ISSPACE` accepts. Note that this is deliberately
 * narrower than `str.isspace()`: the C-level table used while scanning a
 * numeric literal does not include U+001C..U+001F, which is why `int('\x1c5')`
 * fails while `int('\x0b5')` succeeds.
 */
const ASCII_SPACES = new Set([0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x20]);

/**
 * `Py_UNICODE_ISSPACE` for the code points above the ASCII range. These are the
 * characters that get folded to a plain space before a numeric literal is
 * scanned.
 */
const NON_ASCII_SPACES = new Set([
  0x0085, 0x00a0, 0x1680, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a, 0x2028, 0x2029, 0x202f, 0x205f,
  0x3000,
]);

/** Memo table for {@link decimalValue}; digit runs are scanned at most once. */
const digitValues = new Map();

export function isAsciiSpace(codePoint) {
  return ASCII_SPACES.has(codePoint);
}

export function isNonAsciiSpace(codePoint) {
  return NON_ASCII_SPACES.has(codePoint);
}

export function isDecimalDigit(codePoint) {
  return RE_DECIMAL_DIGIT.test(String.fromCodePoint(codePoint));
}

export function isPrintable(codePoint) {
  if (codePoint === 0x20) return true;
  return !RE_NONPRINTABLE.test(String.fromCodePoint(codePoint));
}

/**
 * `Py_UNICODE_TODECIMAL`: the numeric value of a decimal digit, or -1.
 *
 * Unicode lays every decimal digit set out as ten consecutive code points
 * starting at that script's ZERO, but consecutive sets can sit back to back --
 * the mathematical alphanumerics pack five of them into U+1D7CE..U+1D7FF. So
 * walking down to the first non-digit finds the head of the whole contiguous
 * block rather than of one set, and the offset has to be reduced modulo ten.
 */
export function decimalValue(codePoint) {
  const memo = digitValues.get(codePoint);
  if (memo !== undefined) return memo;

  let value = -1;
  if (isDecimalDigit(codePoint)) {
    let blockStart = codePoint;
    while (blockStart > 0 && isDecimalDigit(blockStart - 1)) blockStart -= 1;
    value = (codePoint - blockStart) % 10;
  }

  digitValues.set(codePoint, value);
  return value;
}
==========
/**
 * Python's `repr()` and `str()` for the handful of types this port formats.
 *
 * argparse embeds `%r` of the offending string in its type-error messages and
 * `print(True)` has to come out as `True`, so both spellings are needed.
 */

import { isPrintable } from './unicode.mjs';

const SHORT_ESCAPES = new Map([
  ['\\', '\\\\'],
  ['\t', '\\t'],
  ['\n', '\\n'],
  ['\r', '\\r'],
]);

function escapeCodePoint(codePoint) {
  if (codePoint < 0x100) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  if (codePoint < 0x10000) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

/**
 * `repr()` of a string: single quotes unless the text contains a single quote
 * and no double quote, backslash/tab/newline/carriage-return escaped in short
 * form, and every non-printable code point escaped numerically.
 *
 * @param {string} text
 * @returns {string}
 */
export function reprString(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";

  let out = quote;
  for (const character of text) {
    if (character === quote) {
      out += `\\${character}`;
      continue;
    }
    const short = SHORT_ESCAPES.get(character);
    if (short !== undefined) {
      out += short;
      continue;
    }
    const codePoint = character.codePointAt(0);
    out += isPrintable(codePoint) ? character : escapeCodePoint(codePoint);
  }
  return out + quote;
}

/**
 * `str()`/`print()` of a value. Booleans are the reason this exists: Python
 * spells them `True` and `False`.
 *
 * @param {unknown} value
 * @returns {string}
 */
export function pyStr(value) {
  if (value === true) return 'True';
  if (value === false) return 'False';
  if (value === null || value === undefined) return 'None';
  if (typeof value === 'bigint') return value.toString();
  if (typeof value === 'string') return value;
  return String(value);
}

/**
 * `repr()` of a value: like {@link pyStr} except strings come back quoted.
 *
 * @param {unknown} value
 * @returns {string}
 */
export function pyRepr(value) {
  if (typeof value === 'string') return reprString(value);
  return pyStr(value);
}
=========
/**
 * Stand-ins for the CPython exception types this port needs to distinguish.
 *
 * Only the pieces the migration relies on are modelled: `argparse` catches
 * `ValueError` and `TypeError` coming out of an argument's `type` callable and
 * turns them into its own "invalid <type> value" message, so the port needs the
 * two to be tellable apart from ordinary JavaScript errors.
 */

export class PyException extends Error {
  constructor(message) {
    super(message);
    this.name = this.constructor.name;
  }
}

export class PyValueError extends PyException {}

export class PyTypeError extends PyException {}

/**
 * Raised in place of CPython's `SystemExit`. The entry point catches it so that
 * the process exits with argparse's status code instead of a stack trace.
 */
export class SystemExit extends PyException {
  constructor(code = 0) {
    super(`SystemExit: ${code}`);
    this.code = code;
  }
}

